/* Whole operator for the original ATSSC questionnaire workspace. */
const root=document.querySelector("#app");
const ui={tab:"case",state:null,native:null,session:null,notice:"",error:null,pending:null,busy:false,drafts:{},pages:{},source:null,sourcePreview:null,mapped:null,coverage:null,contactSource:null,contactChoices:{},selectedAssignment:null,selectedMessage:null,messagePreview:null,delivery:null,followups:null,history:null,template:null};
const tabs=[["case","Case"],["sources","Original sources"],["coverage","Coverage"],["contacts","Companies and contacts"],["assignments","Assignments"],["messages","Communications"],["followups","Follow-ups"],["exports","Export and history"]];
const h=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const j=v=>JSON.stringify(v,null,2);
const id=()=>crypto.randomUUID();
const stamp=()=>new Date().toISOString();
const bool=v=>v==="on"||v===true;
const dollars=v=>h(v??"");
const list=v=>String(v||"").split(/[\n,]/).map(x=>x.trim()).filter(Boolean);
function json(v,otherwise={}){if(!String(v||"").trim())return otherwise;try{return JSON.parse(v);}catch{throw Error("Enter complete valid JSON in the advanced field.");}}
function errorText(e){return e?.message||String(e);}
function opt(items,value,empty){return(empty===undefined?"":'<option value="">'+h(empty)+'</option>')+items.map(x=>{const v=typeof x==="string"?x:x.value,l=typeof x==="string"?x:x.label;return'<option value="'+h(v)+'"'+(String(v)===String(value)?" selected":"")+'>'+h(l)+'</option>';}).join("");}
function field(label,name,value="",type="text",extra=""){return'<label>'+h(label)+'<input type="'+type+'" name="'+h(name)+'" value="'+h(value)+'" '+extra+'></label>';}
function area(label,name,value="",extra=""){return'<label class="wide">'+h(label)+'<textarea name="'+h(name)+'" '+extra+'>'+h(value)+'</textarea></label>';}
function select(label,name,items,value,empty){return'<label>'+h(label)+'<select name="'+h(name)+'">'+opt(items,value,empty)+'</select></label>';}
function check(label,name,value=false,extra=""){return'<label class="check"><input type="checkbox" name="'+h(name)+'"'+(value?" checked":"")+" "+extra+'>'+h(label)+'</label>';}
function button(label,action,key="",extra=""){return'<button type="button" data-action="'+action+'" data-id="'+h(key)+'" '+extra+'>'+h(label)+'</button>';}
function submit(label){return'<button type="submit">'+h(label)+'</button>';}
function summary(label,value){return'<div class="stat"><span>'+h(label)+'</span><strong>'+h(value)+'</strong></div>';}
function empty(text){return'<p class="empty">'+h(text)+'</p>';}
function details(label,value){return'<details><summary>'+h(label)+'</summary><pre>'+h(j(value))+'</pre></details>';}
function downloads(links){return'<div class="actions">'+links.map(([label,url])=>'<a class="button" href="'+h(url)+'">'+h(label)+'</a>').join("")+'</div>';}
function form(name,contents,mutation=true){return'<form data-form="'+name+'"'+(mutation?' data-mutation="true"':"")+'><fieldset'+(ui.pending&&mutation?' disabled':"")+'><div class="form-grid">'+contents+'</div></fieldset></form>';}
function pageTable(key,headers,rows,rowFn){const size=50,total=rows.length,max=Math.max(0,Math.ceil(total/size)-1),page=Math.min(ui.pages[key]||0,max);ui.pages[key]=page;return'<div class="table-wrap"><table><thead><tr>'+headers.map(x=>'<th>'+h(x)+'</th>').join("")+'</tr></thead><tbody>'+rows.slice(page*size,(page+1)*size).map(rowFn).join("")+'</tbody></table></div><div class="pager"><span>'+h(total?String(page*size+1)+"–"+Math.min(total,(page+1)*size)+" of "+total:"0 rows")+'</span>'+button("Previous","page",key+"|"+(page-1),page<=0?"disabled":"")+button("Next","page",key+"|"+(page+1),page>=max?"disabled":"")+'</div>';}
function rowsJSON(rows){return pageTable("raw",["Original row","Values and interpretation","Issues"],rows,r=>'<tr><td>'+h(r.source?.row_number||r.row_number||r.id)+'</td><td>'+details(r.company_name||r.company_id||"Original values",r)+'</td><td>'+h([...(r.errors||[]),...(r.warnings||[])].map(x=>x.message||x.code).join("; "))+'</td></tr>');}
function sourceOptions(kind){return(ui.state.sources||[]).filter(x=>!kind||x.kind===kind).map(x=>({value:x.id,label:x.name+(x.current?"":" · earlier edition")}));}
function companyOptions(){return ui.state.companies.map(x=>({value:x.id,label:x.name+" ["+x.id+"]"}));}
function publicationOptions(){return(ui.native.publications||[]).map(x=>({value:x.id,label:(ui.native.questionnaires.find(q=>q.id===x.questionnaire_id)?.name||x.questionnaire_id)+" · definition "+x.definition_version}));}
function assignmentOptions(){return ui.state.assignments.map(x=>({value:x.id,label:x.company.name+" · "+x.contact.language+" · "+x.respondent.status}));}
function templateOptions(){return ui.state.templates.map(x=>({value:x.id,label:x.name+" · "+x.language+" · "+x.kind}));}
function pendingKey(){return"atssc-outreach:"+ui.state.workspace_id;}
function keepPending(){try{sessionStorage.setItem(pendingKey(),JSON.stringify(ui.pending));ui.pendingSaved=true;}catch{sessionStorage.setItem(pendingKey(),JSON.stringify({method:ui.pending.method,params:{request_id:ui.pending.params.request_id,id:ui.pending.params.id},bodyMissing:true}));ui.pendingSaved=false;}}
function clearPending(){ui.pending=null;sessionStorage.removeItem(pendingKey());}
async function request(path,body){let r;try{r=await fetch(path,{method:body===undefined?"GET":"POST",credentials:"same-origin",headers:body===undefined?{}:{"Content-Type":"application/json"},body:body===undefined?undefined:JSON.stringify(body)});}catch(e){e.uncertain=true;throw e;}let data;try{data=await r.json();}catch{const e=Error("The application response could not be read. Recover the original operation before retrying.");e.uncertain=true;throw e;}if(!r.ok||data.error){const raw=data.error,err=Error(typeof raw==="string"?raw:raw?.message||"The application rejected this operation.");err.code=raw?.code;err.detail=raw?.detail;err.status=r.status;err.definitive=r.status>=400&&r.status<500&&!["WORKSPACE_COMMIT_UNKNOWN","COMMIT_UNKNOWN","COMMIT_UNCERTAIN"].includes(err.code);throw err;}return data;}
async function call(method,params={}){return(await request("/api/invoke",{method:method.startsWith("outreach.")?method:"outreach."+method,params})).result;}
async function native(method,params={}){return(await request("/api/invoke",{method,params})).result;}
async function refresh(){const [state,nativeState]=await Promise.all([call("status"),native("status")]);ui.state=state;ui.native=nativeState;render();}
async function mutate(method,params,options={}){if(ui.pending)throw Error("Recover the retained operation before starting another change.");const actor=document.querySelector("#actor")?.value.trim()||sessionStorage.getItem("atssc-operator")||"",reason=options.reason||document.querySelector("#reason")?.value.trim()||"";if(!actor||!reason)throw Error("Enter the operator name and the reason above.");sessionStorage.setItem("atssc-operator",actor);ui.pending={method,params:{...params,actor,reason,request_id:id(),expected_revision:ui.state.revision}};keepPending();return executePending();}
async function executePending(){const operation=ui.pending;if(!operation||operation.bodyMissing)throw Error("Recover this operation by its retained ID. Its complete source body remains with the original file.");ui.busy=true;render();try{const result=await call(operation.method,operation.params);clearPending();ui.notice="Saved "+operation.method.replaceAll("_"," ")+". Original request "+operation.params.request_id;ui.error=null;await refresh();return result;}catch(e){if(e.definitive)clearPending();throw e;}finally{ui.busy=false;render();}}
async function recoverPending(){if(!ui.pending)return;const p=ui.pending;try{let result;try{result=await call("operation",{request_id:p.params.request_id+(p.method==="dispatch"?":result":"")});}catch(e){if(e.code!=="NOT_FOUND")throw e;if(p.method==="dispatch"){const state=await call("get_message",{id:p.params.id});if(state.message.delivery.state!=="QUEUED"){clearPending();ui.selectedMessage=state.message;ui.notice="The original dispatch is recorded as "+state.message.delivery.state+". Provider results continue against this same message.";await refresh();return;}}ui.notice="The original request has not committed. Its same retained body can be retried.";render();return;}clearPending();ui.notice="Recovered original operation "+result.operation.id+".";await refresh();}catch(e){showError(e);}}
async function filePayload(file){if(!file)throw Error("Choose the complete original file.");if(file.size>64*1024*1024)throw Error("The original source must fit the application's 64 MiB file limit.");const a=new Uint8Array(await file.arrayBuffer());let text="";for(let i=0;i<a.length;i+=32768)text+=String.fromCharCode(...a.subarray(i,i+32768));return{name:file.name,content_base64:btoa(text)};}
function showError(e){ui.error=errorText(e)+(e?.detail?" · "+j(e.detail):"");render();}
function restoreDrafts(){for(const f of root.querySelectorAll("form[data-form]")){const saved=ui.drafts[f.dataset.form];if(!saved)continue;for(const [name,value]of Object.entries(saved)){const element=f.elements.namedItem(name);if(!element||element.type==="file"||element.type==="password")continue;if(element.type==="checkbox")element.checked=!!value;else if(element.value!==String(value))element.value=value;}}}
function captureDraft(form){if(!form||["login","public-entry","respondent-contact"].includes(form.dataset.form))return;const values={};for(const el of form.elements){if(!el.name||["file","password","submit"].includes(el.type))continue;values[el.name]=el.type==="checkbox"?el.checked:el.value;}ui.drafts[form.dataset.form]=values;}
function render(){if(!ui.session)return;if(!ui.session.authenticated)return renderLogin();if(ui.session.role==="respondent")return renderRespondent();if(!ui.state){root.innerHTML='<main><h1>Opening companies and communications…</h1></main>';return;}const body=views[ui.tab]?.()||views.case();root.innerHTML='<header><div><a href="/operator">Questionnaire Operations</a><h1>Companies and communications</h1><p>'+h(ui.state.profile?.case_reference||"Set up a case")+' · Workspace '+h(ui.state.workspace_id)+'</p></div><div class="actions">'+button("Refresh","refresh")+button("Sign out","logout")+'</div></header><nav aria-label="Operating sections">'+tabs.map(([key,label])=>'<button type="button" data-action="tab" data-id="'+key+'" aria-current="'+(key===ui.tab?"page":"false")+'">'+h(label)+'</button>').join("")+'</nav><main><div class="operator"><label>Operator<input id="actor" value="'+h(sessionStorage.getItem("atssc-operator")||"")+'" autocomplete="name"></label><label>Reason for the next change<input id="reason" value="'+h(ui.reason||"")+'" placeholder="Describe the source or operating decision"></label><span>Edition '+h(ui.state.revision)+'</span></div>'+(ui.pending?'<section class="pending"><h2>Original operation pending</h2><p>'+h(ui.pending.method)+' · '+h(ui.pending.params.request_id)+'</p><p>Recover its recorded outcome before another change.</p>'+button("Recover original operation","recover")+button("Retry same retained request","retry","",ui.pending.bodyMissing?"disabled":"")+'</section>':"")+(ui.error?'<div role="alert" class="notice"><strong>Review required</strong><p>'+h(ui.error)+'</p></div>':"")+(ui.notice?'<p role="status" class="notice">'+h(ui.notice)+'</p>':"")+body+'</main><footer>Original source files, selected company identities and questionnaire records stay together in the saved project.</footer>';restoreDrafts();if(ui.busy||ui.pending){for(const f of root.querySelectorAll('form[data-mutation] fieldset'))f.disabled=true;for(const b of root.querySelectorAll("[data-mutation-action]"))b.disabled=true;}}
function renderLogin(){root.innerHTML='<main class="login"><a href="/operator">Questionnaire Operations</a><h1>Companies and communications</h1><p>Open the existing operator session using this project’s private access code.</p>'+(ui.error?'<p role="alert">'+h(ui.error)+'</p>':"")+form("login",field("Operator access code","access_code","","password",'required autocomplete="current-password"')+submit("Open operator session"),false)+'</main>';}
const views={};
views.case=()=>{const p=ui.state.profile||{},settings=p.followup_settings||{};return'<section><h2>Case and delivery settings</h2><p>Questionnaires and responses use the original application. This desk prepares company coverage, assignments, delivery and follow-up from those same records.</p><div class="stats">'+summary("Companies",ui.state.companies.length)+summary("Contacts",ui.state.contacts.length)+summary("Assignments",ui.state.assignments.length)+summary("Original sources",ui.state.sources.length)+'</div>'+form("profile",
field("Case reference","case_reference",p.case_reference,"text","required")+field("Case title","case_title",p.case_title,"text","required")+field("Organization","organization_name",p.organization_name,"text","required")+field("Support contact","support_contact",p.support_contact,"text","required")+field("Original notice · ISO date with timezone","notice_at",p.notice_at,"text",'required placeholder="2026-10-12T14:00:00-04:00"')+field("Response deadline · ISO date with timezone","due_at",p.due_at,"text","required")+field("Deployed application origin","application_url",p.application_url||location.origin,"url","required")+field("Sender email","sender_email",p.sender_email,"email")+field("Staff notification email","staff_email",p.staff_email,"email")+field("First follow-up after hours","initial_followup_hours",settings.initial_followup_hours??24,"number",'min="0" max="720" step="1" required')+field("Pre-deadline follow-up, days","before_due_days",settings.before_due_days??2,"number",'min="0" max="365" step="1" required')+check("Prepare confirmation and revision-request messages automatically from original responses","automatic_notifications",p.automatic_notifications)+check("Enable the configured follow-up worker","automatic",settings.automatic)+check("Allow due follow-ups after the deadline","after_due",settings.after_due)+submit("Save case settings"))+'<h3>Native email transport</h3><p>The operating host uses its configured SMTP relay. Credentials stay in its environment. A provider accepting a message is shown separately from final delivery; the original MIME and native delivery results remain downloadable.</p><p><a href="/respondent-operations/guide">Open the complete operating guide</a></p>'+details("Current follow-up and case settings",p)+'</section>';};
views.sources=()=>{const source=ui.sourcePreview?.source,columns=source?.columns||[],kind=ui.sourceKind||"TRADE",mapFields=kind==="TRADE"?["company_id","company_name","hs_code","country","value_for_duty"]:["company_id","company_name","contact_name","email","phone","postal_address","country","role","language"];let out='<section><h2>Import the complete original table</h2><p>Choose its worksheet, header and columns explicitly. Source bytes and every included row remain in the saved project.</p>'+form("source",field("Original CSV or XLSX","file","","file",'accept=".csv,.xlsx,.txt"')+select("Source kind","kind",["TRADE","CONTACTS"],kind)+select("Format","format",["CSV","XLSX"],ui.source?.options?.format||"CSV")+field("Worksheet name · exact when XLSX","sheet",ui.source?.options?.sheet||"")+field("Header row","header_row",ui.source?.options?.header_row||1,"number",'min="1" step="1" required')+select("Text encoding for CSV","encoding",["utf-8-sig","utf-8","cp1252","latin-1"],ui.source?.options?.encoding||"utf-8-sig")+select("CSV delimiter","delimiter",[{value:",",label:"Comma"},{value:";",label:"Semicolon"},{value:"\t",label:"Tab"}],ui.source?.options?.delimiter||",")+submit("Read original table"),false);if(source){out+='<div class="stats">'+summary("Original file",source.file.name)+summary("Bytes",source.file.bytes)+summary("Rows",source.rows?.length||0)+'</div>';if(source.requires_sheet)out+='<h3>Original worksheets</h3>'+details("Choose one exact sheet name above",source.sheets);else{out+='<h3>Map original columns</h3>'+form("source-map",mapFields.map(name=>select(name.replaceAll("_"," "),"map."+name,columns.map(c=>({value:c.id,label:c.id+" · "+(c.name||c.label||c.header||"")})),ui.mapping?.[name],"Not mapped")).join("")+(kind==="TRADE"?field("Source currency","currency",ui.mapSettings?.currency||"CAD","text",'required pattern="[A-Z]{3}"'):select("Default contact language","default_language",["EN","FR"],ui.mapSettings?.default_language||"EN"))+select("Decimal mark","decimal_separator",[".",","],ui.mapSettings?.numbers?.decimal_separator||".")+select("Grouping mark","group_separator",[{value:"",label:"No grouping"},{value:",",label:"Comma"},{value:".",label:"Period"},{value:" ",label:"Space"}],ui.mapSettings?.numbers?.group_separator||"")+area("Additional custom fields · JSON field name to original column ID","custom_mapping",j(ui.customMapping||{}))+area("Reviewed numeric identifier interpretation · JSON by field","identifiers",j(ui.mapSettings?.identifiers||{}))+field("Fields whose cached Excel formula results are reviewed","accept_cached_formula_fields",(ui.mapSettings?.accept_cached_formula_fields||[]).join(", "))+submit("Review complete interpretation"),false)+details("Original columns and worksheet edition",{columns,sheet:source.selected_sheet,interpretation:source.interpretation});}}if(ui.mapped){out+='<h3>Interpreted source rows</h3><div class="stats">'+summary("Rows",ui.mapped.counts.rows)+summary("Valid",ui.mapped.counts.valid)+summary("Need interpretation",ui.mapped.counts.invalid)+summary("Have source notes",ui.mapped.counts.with_warnings)+'</div>'+rowsJSON(ui.mapped.rows)+form("source-retain",select("Earlier source edition corrected by this import","supersedes_id",sourceOptions(kind),"","New source edition")+submit("Retain original file and reviewed mapping"));}out+='<h3>Retained source editions</h3>'+pageTable("sources",["Source","Kind","Edition","Original files"],ui.state.sources,r=>'<tr><td>'+h(r.name)+'<small>'+h(r.id)+'</small></td><td>'+h(r.kind)+'</td><td>'+h(r.current?"Current":"Earlier")+(r.supersedes_id?'<small>Corrects '+h(r.supersedes_id)+'</small>':"")+'</td><td>'+downloads([["Original","/api/outreach/files/source/"+r.id+"/original"],["Complete mapping","/api/outreach/files/source/"+r.id+"/json"]])+'</td></tr>')+'</section>';return out;};
views.coverage=()=>{let out='<section><h2>Representative company coverage</h2><p>Set this case’s target. The original RFI gives 80% as an example; the selected value and its basis are explicit operating inputs. Recommendations retain all original company values and exclusions.</p>'+form("coverage-preview",select("Original trade edition","source_id",sourceOptions("TRADE"),ui.coverageSourceId,"Select source")+field("Target coverage, percent","target_percent",ui.coveragePolicy?.target_percent??"","text",'required placeholder="Case target"')+select("Grouping","group_by",[{value:"hs_code,country",label:"HS code and country"},{value:"hs_code",label:"HS code"},{value:"country",label:"Country"}],(ui.coveragePolicy?.group_by||["hs_code","country"]).join(","))+select("HS digits","hs_digits",[{value:"",label:"Keep original complete code"},..."2,4,6,8,10".split(",")],ui.coveragePolicy?.hs_digits||"")+select("Coverage value basis","value_basis",[{value:"NET_COMPANY",label:"Net value per company · negative adjustments retained"},{value:"POSITIVE_ROWS",label:"Positive rows · original negative values reported"}],ui.coveragePolicy?.value_basis||"NET_COMPANY")+select("Selection","mode",[{value:"AUTO",label:"Recommend to reach the target"},{value:"MANUAL",label:"Only explicitly included companies"}],ui.coveragePolicy?.mode||"AUTO")+check("I reviewed the original negative values and selected basis","negative_values_reviewed",ui.coveragePolicy?.negative_values_reviewed)+field("HS code filter · exact original values","hs_codes",(ui.coveragePolicy?.filters?.hs_codes||[]).join(", "))+field("Country filter · exact original values","countries",(ui.coveragePolicy?.filters?.countries||[]).join(", "))+area("Always include company IDs · comma or newline separated","included_companies",(ui.coveragePolicy?.included_companies||[]).join("\n"))+area("Company exclusions · JSON with company_id and reason","excluded_companies",j(ui.coveragePolicy?.excluded_companies||[]))+area("Invalid source-row dispositions · JSON with row_id, action EXCLUDE and reason","row_dispositions",j(ui.coveragePolicy?.row_dispositions||[]))+area("Interested parties and referrals · JSON with company_id, name, reason and original source","additional_companies",j(ui.coveragePolicy?.additional_companies||[]))+submit("Calculate coverage"),false);if(ui.coverage){const r=ui.coverage;out+='<h3>Coverage review</h3><div class="stats">'+summary("Selected companies",r.counts.selected_companies)+summary("Original rows",r.counts.original_rows)+summary("Trade groups",r.counts.trade_groups)+summary("Ready",r.ready?"Yes":"Review needed")+'</div>'+pageTable("coverage-groups",["Trade group","Original net","Negative value","Basis","Selected value","Coverage","Review"],r.groups,g=>'<tr><td>'+h(Object.entries(g.fields).map(([k,v])=>k+": "+v).join(" · "))+'</td><td>'+h(g.net_value)+'</td><td>'+h(g.negative_value)+'</td><td>'+h(g.coverage_basis)+'</td><td>'+h(g.selected_value)+'</td><td>'+h(g.achieved_percent??"No positive basis")+"% / "+h(g.target_percent)+'%</td><td>'+details(g.meets_target?"Meets target":"Shortfall",g)+'</td></tr>')+details("Selected companies and their original source rows",r.selected_companies)+(r.problems.length?details("Coverage problems",r.problems):"")+form("coverage-save",field("Retained coverage name","name","","text","required")+submit("Save selection and company records"));}out+='<h3>Saved coverage editions</h3>'+pageTable("plans",["Name","Source","Companies","Original review"],ui.state.coverage,p=>'<tr><td>'+h(p.name)+'</td><td>'+h(p.source_id)+'</td><td>'+h(p.report.counts.selected_companies)+'</td><td>'+details("Complete saved coverage",p)+'</td></tr>')+'</section>';return out;};

views.contacts=()=>{const c=ui.contact||{},company=ui.company||{};let out='<section><h2>Companies and contacts</h2><p>Coverage, a contact-source row or a recorded referral supplies the original company identity. A general inbox can be forwarded to the authorized respondent without creating another questionnaire assignment.</p><h3>Company record</h3>'+form("company",field("Company identifier","id",company.id,"text","required")+field("Company name","name",company.name,"text","required")+field("Original source or referral reference","source_reference","","text",company.id?"":"required")+area("Known names · one per line","aliases",(company.aliases||[]).join("\n"))+area("Company note","note",company.note)+check("Active company","active",company.active??true)+submit(company.id?"Save company edition":"Save company"))+pageTable("companies",["Company","Identity","Contacts","Action"],ui.state.companies,c=>'<tr><td>'+h(c.name)+'</td><td>'+h(c.id)+'</td><td>'+ui.state.contacts.filter(x=>x.company_id===c.id).length+'</td><td>'+button("Edit company","edit-company",c.id)+'</td></tr>')+'<h3>Contact record</h3>'+form("contact",select("Original company","company_id",companyOptions(),c.company_id,"Select company")+field("Contact name","contact_name",c.contact_name)+field("Email","email",c.email,"email")+select("Contact route","kind",["PERSON","GENERIC_INBOX","PUBLIC_ENTRY"],c.kind||"PERSON")+select("Language","language",["EN","FR"],c.language||"EN")+field("Phone","phone",c.phone)+field("Role","role",c.role)+field("Country","country",c.country)+area("Postal address","postal_address",c.postal_address)+field("Original contact source","source_reference","","text",c.id?"":"required")+area("Custom fields · named JSON values","custom",j(c.custom||{}))+area("Contact note","note",c.note)+check("Active contact","active",c.active??true)+submit(c.id?"Save contact edition":"Add contact"))+pageTable("contacts",["Company","Contact and route","Language","Original edition","Actions"],ui.state.contacts,r=>'<tr><td>'+h(r.company_name)+'</td><td>'+h(r.contact_name||r.kind)+'<small>'+h(r.email||r.phone||r.postal_address)+'</small></td><td>'+h(r.language)+'</td><td>'+r.version+'</td><td>'+button("Edit contact","edit-contact",r.id)+details("Source and custom fields",{source:r.source,custom:r.custom})+'</td></tr>')+'<h3>Receive a complete contact source</h3>'+form("contacts-source",select("Retained original contact edition","source_id",sourceOptions("CONTACTS"),ui.contactSource?.id,"Select contact source")+submit("Review all original contact rows"),false);if(ui.contactSource){const rows=ui.contactSource.report.mapped.rows;out+='<p>Every original row needs a disposition. CREATE and UPDATE preserve source links; SKIP requires a source reason. Differing company names need an explicit name policy.</p>'+button("Select CREATE for valid new rows without duplicate candidates","contact-bulk-create")+pageTable("contact-import",["Source row and company","Contact","Disposition","Existing contact / name policy","Reason"],rows,r=>{const d=ui.contactChoices[r.id]||{};return'<tr data-contact-row="'+h(r.id)+'"><td>'+h(r.company_name)+" ["+h(r.company_id)+"]"+'<small>'+h(r.source.row_number||r.source.row||r.id)+'</small>'+details("Original source and issues",r)+'</td><td>'+h(r.contact_name)+'<small>'+h(r.email)+'</small></td><td><select data-choice="action" data-row="'+h(r.id)+'">'+opt(["CREATE","UPDATE","KEEP_EXISTING","SKIP"],d.action,"Choose")+'</select></td><td><select data-choice="contact_id" data-row="'+h(r.id)+'">'+opt(ui.state.contacts.filter(x=>x.company_id===r.company_id).map(x=>({value:x.id,label:x.contact_name+" · "+x.email})),d.contact_id,"Existing contact")+'</select><select data-choice="company_name_policy" data-row="'+h(r.id)+'">'+opt(["KEEP_CURRENT","REPLACE"],d.company_name_policy,"Review differing name")+'</select><select data-choice="kind" data-row="'+h(r.id)+'">'+opt(["PERSON","GENERIC_INBOX"],d.kind||"PERSON")+'</select></td><td><input data-choice="reason" data-row="'+h(r.id)+'" value="'+h(d.reason||"")+'" aria-label="Disposition reason"></td></tr>';})+form("contacts-receive",submit("Receive all reviewed source rows"));}return out+'</section>';};
views.assignments=()=>{let out='<section><h2>Questionnaire assignments</h2><p>Each selected company uses one original respondent per published questionnaire. Existing invitations and accepted revisions remain with that same respondent.</p>'+form("assignments",select("Published questionnaire","publication_id",publicationOptions(),"","Select publication")+select("Selected coverage edition","coverage_id",ui.state.coverage.map(x=>({value:x.id,label:x.name})),"","All reviewed companies")+'<div class="wide table-wrap"><table><thead><tr><th>Select</th><th>Company</th><th>Contact</th></tr></thead><tbody>'+ui.state.companies.filter(c=>c.active).map(c=>'<tr><td><input type="checkbox" name="assign.'+h(c.id)+'" aria-label="Assign '+h(c.name)+'"></td><td>'+h(c.name)+'<small>'+h(c.id)+'</small></td><td><select name="contact.'+h(c.id)+'">'+opt(ui.state.contacts.filter(x=>x.company_id===c.id&&x.active).map(x=>({value:x.id,label:x.contact_name+" · "+(x.email||x.phone||x.kind)+" · "+x.language})),"","Select contact")+'</select></td></tr>').join("")+'</tbody></table></div>'+submit("Create selected original assignments"))+pageTable("assignments",["Company","Contact","Original response","Deadline","Actions"],ui.state.assignments,a=>'<tr><td>'+h(a.company.name)+'</td><td>'+h(a.contact.contact_name||a.contact.kind)+'<small>'+h(a.contact.email)+'</small></td><td>'+h(a.respondent.status)+'<small>Revision '+h(a.respondent.version)+'</small></td><td>'+h(a.due_at)+(a.paused?'<small>Paused</small>':"")+'</td><td>'+button("Open assignment","assignment",a.id)+'</td></tr>');if(ui.selectedAssignment){const a=ui.selectedAssignment.assignment;out+='<h3>'+h(a.company.name)+' · original assignment</h3><p><a href="'+h(a.entry_path)+'">Open this respondent’s questionnaire</a></p>'+details("Private access information",{respondent_id:a.respondent_id,access_code:a.access_code,entry_path:a.entry_path})+form("assignment-edit",select("Current company contact","contact_id",ui.state.contacts.filter(c=>c.company_id===a.company_id).map(c=>({value:c.id,label:c.contact_name+" · "+c.email+" · "+c.language})),a.contact_id)+field("Notice date with timezone","notice_at",a.notice_at,"text","required")+field("Response deadline with timezone","due_at",a.due_at,"text","required")+select("Company review","registration_state",["REVIEWED_COMPANY","NEW_COMPANY_CONTACT_REVIEW"],a.registration_state)+check("Active assignment","active",a.active)+check("Pause communication","paused",a.paused)+area("Assignment note","note",a.note)+submit("Save assignment edition"))+details("Complete original revisions and reviews",ui.selectedAssignment.original_response); }out+='<h3>Public questionnaire entry</h3><p>A public entry registers its own company and contact for staff review, then returns that respondent’s private access code. It cannot claim an existing company’s private questionnaire.</p>'+form("public-link",field("Public link name","name","","text","required")+select("Original publication","publication_id",publicationOptions(),"","Select publication")+select("Entry language","language",["EN","FR"],"EN")+field("Expires with timezone","expires_at",ui.state.profile?.due_at||"","text","required")+submit("Create public entry link"))+pageTable("public-links",["Name","Language","Expires","Actions"],ui.state.public_links,l=>'<tr><td>'+h(l.name)+'</td><td>'+h(l.language)+'</td><td>'+h(l.expires_at)+'</td><td>'+button("Show entry link","public-link",l.id)+'</td></tr>')+(ui.publicLink?details("Original public entry link",ui.publicLink):"");return out+'</section>';};
views.messages=()=>{const t=ui.template||{};let out='<section><h2>Communications</h2><p>Review the full recipient, message and original response before queuing. Native SMTP submission keeps its exact MIME; native delivery notifications update the same message.</p><div class="actions">'+button("Install the ten English and French templates","install-templates","",'data-mutation-action')+button("Prepare missing original response notices","sync-notifications","",'data-mutation-action')+'</div><h3>Message template</h3>'+form("template",field("Template name","name",t.name,"text","required")+select("Message type","kind",["INVITATION","REMINDER","SUBMISSION_CONFIRMATION","STAFF_NOTIFICATION","REVISION_REQUEST"],t.kind||"INVITATION")+select("Language","language",["EN","FR"],t.language||"EN")+field("Subject","subject",t.subject,"text","required")+area("Complete message body","body",t.body,"required rows=12")+submit(t.id?"Save template edition":"Save new template"))+pageTable("templates",["Template","Type","Language","Action"],ui.state.templates,x=>'<tr><td>'+h(x.name)+'</td><td>'+h(x.kind)+'</td><td>'+h(x.language)+'</td><td>'+button("Edit template","template",x.id)+'</td></tr>')+'<h3>Review an original communication</h3>'+form("message-preview",select("Original assignment","assignment_id",assignmentOptions(),ui.messageParams?.assignment_id,"Select assignment")+select("Template","template_id",templateOptions(),ui.messageParams?.template_id,"Select template")+field("Original due follow-up key · for reminders","followup_key",ui.messageParams?.followup_key||"")+submit("Preview complete message"),false);if(ui.messagePreview){const m=ui.messagePreview;out+='<article class="message"><h3>'+h(m.rendered.subject)+'</h3><dl><dt>From</dt><dd>'+h(m.sender)+'</dd><dt>To</dt><dd>'+h(m.recipient)+'</dd><dt>Original response</dt><dd>'+h(m.respondent_status)+' · '+h(m.respondent_version)+'</dd></dl><pre class="prose">'+h(m.rendered.body)+'</pre></article>'+form("message-retain",submit("Queue this reviewed message"));}out+='<h3>Saved communication history</h3>'+pageTable("messages",["Company","Message","Recipient","Delivery","Actions"],ui.state.messages,m=>'<tr><td>'+h(ui.state.assignments.find(a=>a.id===m.assignment_id)?.company.name||m.assignment_id)+'</td><td>'+h(m.kind)+'<small>'+h(m.created)+'</small></td><td>'+h(m.recipient)+'</td><td>'+h(m.delivery.state)+'</td><td>'+button("Open message","message",m.id)+'</td></tr>');if(ui.selectedMessage){const m=ui.selectedMessage;out+='<h3>Original message '+h(m.id)+'</h3><article class="message"><h4>'+h(m.rendered.subject)+'</h4><p>To '+h(m.recipient)+' · From '+h(m.sender)+'</p><pre class="prose">'+h(m.rendered.body)+'</pre></article><p><strong>Delivery: '+h(m.delivery.state)+'</strong></p><div class="actions">'+(m.delivery.state==="QUEUED"?button("Submit this queued message through the configured relay","dispatch",m.id,'data-mutation-action'):"")+(["QUEUED","REJECTED"].includes(m.delivery.state)?button("Cancel this communication","cancel-message",m.id,'data-mutation-action'):"")+(m.delivery.state==="SENDING"?button("Record interrupted dispatch outcome as unknown","record-unknown",m.id,'data-mutation-action'):"")+button("Refresh original message","message",m.id)+'</div>'+downloads([["Complete original record","/api/outreach/files/message/"+m.id+"/json"],...(m.wire?[["Original MIME","/api/outreach/files/message/"+m.id+"/eml"]]:[])])+details("Original provider events and response identities",{events:m.events,wire:m.wire,trigger_id:m.trigger_id,followup_key:m.followup_key});}out+='<h3>Receive original delivery results</h3>'+form("delivery-preview",field("Original delivery notification or provider JSON","file","","file",'accept=".eml,.json,.txt" required')+select("Original format","format",[{value:"DSN",label:"Native delivery-status notification (.eml)"},{value:"JSON",label:"Original provider JSON with explicit mapping"}],ui.deliveryInput?.format||"DSN")+area("JSON mapping · records pointer, fields and exact provider statuses","mapping",j(ui.deliveryInput?.mapping||{}))+submit("Review original delivery file"),false);if(ui.delivery){out+=pageTable("delivery-preview",["Message","Original recipient","Outcome","Provider time","Original source"],ui.delivery.events,e=>'<tr><td>'+h(e.message_id)+'</td><td>'+h(e.original_recipient||e.mapped_fields?.recipient||e.recipient)+'</td><td>'+h(e.kind)+'</td><td>'+h(e.at)+'</td><td>'+details("Complete provider result",e)+'</td></tr>')+(ui.delivery.problems.length?details("Provider identity review",ui.delivery.problems):"")+form("delivery-retain",submit("Retain reviewed provider results"));}return out+'</section>';};
views.followups=()=>{let out='<section><h2>Follow-up and response assistance</h2><p>The due queue is calculated from the current original respondent status, notice, deadline, correction request and already-retained communications.</p>'+form("followups-read",field("Queue time with timezone","at",ui.followups?.at||stamp(),"text","required")+submit("Refresh due work"),false)+'<div class="actions">'+button("Prepare due configured follow-ups","process-due","queue",'data-mutation-action')+button("Prepare and submit due configured follow-ups","process-due","send",'data-mutation-action')+'</div>';if(ui.followups){out+='<p>'+h(ui.followups.due)+' currently eligible follow-ups.</p>'+pageTable("followups",["Company","Phase","Scheduled","Current decision","Action"],ui.followups.items,x=>'<tr><td>'+h(ui.state.companies.find(c=>c.id===x.company_id)?.name||x.company_id)+'</td><td>'+h(x.phase)+'</td><td>'+h(x.scheduled_at)+'</td><td>'+h(x.eligible?"Due":x.reasons.join(", "))+'</td><td>'+(x.eligible?button("Prepare reminder","prepare-followup",x.key):details("Original decision",x))+'</td></tr>');}out+='<h3>Record a contact or assistance outcome</h3>'+form("followup-log",select("Original assignment","assignment_id",assignmentOptions(),"","Select assignment")+select("Contact route","channel",["PHONE","EMAIL","POSTAL","IN_PERSON","REFERRAL"],"PHONE")+select("Actual outcome","outcome",["CONTACTED","NO_ANSWER","ASSISTANCE","CONTACT_CORRECTION","EXPECTED_RESPONSE","POSTAL_SENT","REFERRED","DECLINED"],"CONTACTED")+field("Original contact time with timezone","at",stamp(),"text","required")+field("Expected response time with timezone · optional","expected_response_at","")+field("Original correspondence or staff record reference","original_source","","text","required")+area("Complete outcome and assistance provided","note","","required")+submit("Save contact outcome"));return out+'</section>';};
views.exports=()=>'<section><h2>Complete operating handover</h2><p>The editable operating workbook contains Companies, Contacts, Assignments, Delivery, Sources, Coverage and Follow-up history. The operating ZIP adds every original source and complete JSON. The complete project ZIP also carries the original authenticated questionnaire application, database, definitions, answers, revisions and reports for cold receiving.</p>'+downloads([["Editable operating workbook","/api/outreach/files/operating.xlsx"],["Complete contacts CSV","/api/outreach/files/operating.csv"],["Complete operating JSON","/api/outreach/files/operating.json"],["Operating files and originals","/api/outreach/files/operating.zip"],["Complete original project","/api/outreach/files/project.zip"]])+'<h3>Original operation history</h3>'+form("history-read",select("Record kind","kind",["company","contact","assignment","coverage","source","message","delivery_source","followup","profile","template","public_link"],ui.historyFilter?.kind,"All records")+field("Original record ID · optional","id",ui.historyFilter?.id||"")+submit("Read history"),false)+(ui.history?pageTable("history",["Sequence","Record","Operator","Time and reason","Original editions"],ui.history.items,r=>'<tr><td>'+h(r.sequence)+'</td><td>'+h(r.kind)+'<small>'+h(r.identity)+'</small></td><td>'+h(r.actor)+'</td><td>'+h(r.created)+'<small>'+h(r.reason)+'</small></td><td>'+details("Before and after",{before:r.before_value,after:r.after_value})+'</td></tr>')+"<p>"+h(ui.history.total)+" complete history rows loaded.</p>":"")+'</section>';

const handlers={};
handlers.login=async(f,d)=>{ui.session=await request("/api/session",{role:"operator",access_code:d.access_code});await refresh();const saved=sessionStorage.getItem(pendingKey());if(saved){try{ui.pending=JSON.parse(saved);}catch{}}render();};
handlers.profile=async(f,d)=>{const result=await mutate("save_profile",{expected_version:ui.state.profile?.version||0,profile:{case_reference:d.case_reference,case_title:d.case_title,organization_name:d.organization_name,support_contact:d.support_contact,notice_at:d.notice_at,due_at:d.due_at,application_url:d.application_url,sender_email:d.sender_email,staff_email:d.staff_email,automatic_notifications:bool(d.automatic_notifications),followup_settings:{initial_followup_hours:Number(d.initial_followup_hours),before_due_days:Number(d.before_due_days),automatic:bool(d.automatic),after_due:bool(d.after_due)}}});delete ui.drafts.profile;return result;};
handlers.source=async(f,d)=>{const file=f.elements.file.files[0];if(file)ui.source=await filePayload(file);if(!ui.source)throw Error("Choose the original file.");ui.sourceKind=d.kind;ui.source.options={format:d.format,header_row:Number(d.header_row),encoding:d.encoding,delimiter:d.delimiter,...(d.sheet?{sheet:d.sheet}:{})};ui.sourcePreview=await call("preview_source",{source:ui.source});ui.mapped=null;ui.mapping=null;delete ui.drafts["source-map"];ui.notice="The complete original table is open. Select the exact columns below.";};
handlers["source-map"]=async(f,d)=>{const mapping={};for(const[k,v]of Object.entries(d))if(k.startsWith("map.")&&v)mapping[k.slice(4)]=v;const custom=json(d.custom_mapping,{});for(const[k,v]of Object.entries(custom))mapping[k.startsWith("custom.")?k:"custom."+k]=v;ui.customMapping=custom;ui.mapping=mapping;ui.mapSettings={...(ui.sourceKind==="TRADE"?{currency:d.currency}:{default_language:d.default_language}),numbers:{decimal_separator:d.decimal_separator,group_separator:d.group_separator},identifiers:json(d.identifiers,{}),accept_cached_formula_fields:list(d.accept_cached_formula_fields)};const result=await call("preview_source",{source:ui.source,kind:ui.sourceKind,mapping,settings:ui.mapSettings});ui.sourcePreview=result;ui.mapped=result.mapping;};
handlers["source-retain"]=async(f,d)=>{if(!ui.mapped)throw Error("Review the original source interpretation first.");const result=await mutate("receive_source",{source:ui.source,kind:ui.sourceKind,mapping:ui.mapping,settings:ui.mapSettings,review_sha256:ui.mapped.review_sha256,...(d.supersedes_id?{supersedes_id:d.supersedes_id}:{})});ui.retainedSource=result.source_id;ui.notice="Original file and complete interpretation retained as "+result.source_id+".";};
handlers["coverage-preview"]=async(f,d)=>{ui.coverageSourceId=d.source_id;ui.coveragePolicy={target_percent:d.target_percent,group_by:d.group_by.split(","),...(d.hs_digits?{hs_digits:Number(d.hs_digits)}:{}),value_basis:d.value_basis,mode:d.mode,negative_values_reviewed:bool(d.negative_values_reviewed),filters:{hs_codes:list(d.hs_codes),countries:list(d.countries)},included_companies:list(d.included_companies),excluded_companies:json(d.excluded_companies,[]),row_dispositions:json(d.row_dispositions,[]),additional_companies:json(d.additional_companies,[])};ui.coverage=await call("preview_coverage",{source_id:d.source_id,policy:ui.coveragePolicy});};
handlers["coverage-save"]=async(f,d)=>{if(!ui.coverage)throw Error("Calculate and review the complete coverage first.");await mutate("save_coverage",{source_id:ui.coverageSourceId,policy:ui.coveragePolicy,review_sha256:ui.coverage.review_sha256,name:d.name});delete ui.drafts["coverage-save"];};
handlers.company=async(f,d)=>{const old=ui.company;const sources=[...(old?.sources||[]),...(d.source_reference?[{kind:"OPERATOR_REFERENCE",reference:d.source_reference,at:stamp()}]:[])];await mutate("save_company",{expected_version:old?.id===d.id?old.version:0,company:{id:d.id,name:d.name,aliases:String(d.aliases||"").split(/\r?\n/).map(x=>x.trim()).filter(Boolean),active:bool(d.active),sources,note:d.note}});ui.company=null;delete ui.drafts.company;};
handlers.contact=async(f,d)=>{const company=ui.state.companies.find(c=>c.id===d.company_id);if(!company)throw Error("Choose an original company.");const old=ui.contact;await mutate("save_contact",{...(old?{id:old.id,expected_version:old.version}:{}),contact:{company_id:company.id,company_name:company.name,contact_name:d.contact_name,email:d.email,phone:d.phone,postal_address:d.postal_address,country:d.country,role:d.role,kind:d.kind,language:d.language,custom:json(d.custom,{}),active:bool(d.active),note:d.note,source:d.source_reference?{kind:"OPERATOR_REFERENCE",reference:d.source_reference,previous:old?.source,at:stamp()}:old?.source}});ui.contact=null;delete ui.drafts.contact;};
handlers["contacts-source"]=async(f,d)=>{ui.contactSource=await call("get_source",{source_id:d.source_id,complete:true});ui.contactChoices=Object.fromEntries((ui.contactSource.contact_links||[]).map(x=>[x.row_id,{action:"KEEP_EXISTING",contact_id:x.contact_id}]));ui.pages["contact-import"]=0;};
handlers["contacts-receive"]=async()=>{const rows=ui.contactSource.report.mapped.rows.map(r=>{const x=ui.contactChoices[r.id]||{};const contact=ui.state.contacts.find(c=>c.id===x.contact_id);return{row_id:r.id,...x,...(contact?{expected_version:contact.version}:{})};});await mutate("receive_contacts",{source_id:ui.contactSource.id,rows});ui.notice="Every original contact-source row has its saved disposition.";};
handlers.assignments=async(f,d)=>{const assignments=Object.keys(d).filter(k=>k.startsWith("assign.")&&bool(d[k])).map(k=>{const company_id=k.slice(7);return{company_id,contact_id:d["contact."+company_id],publication_id:d.publication_id,...(d.coverage_id?{coverage_id:d.coverage_id}:{})};});if(!assignments.length)throw Error("Select at least one company and its original contact.");await mutate("assign",{assignments});delete ui.drafts.assignments;};
handlers["assignment-edit"]=async(f,d)=>{const a=ui.selectedAssignment.assignment;await mutate("update_assignment",{id:a.id,expected_version:a.version,assignment:{contact_id:d.contact_id,notice_at:d.notice_at,due_at:d.due_at,registration_state:d.registration_state,active:bool(d.active),paused:bool(d.paused),note:d.note}});ui.selectedAssignment=await call("get_assignment",{id:a.id});delete ui.drafts["assignment-edit"];};
handlers["public-link"]=async(f,d)=>{ui.publicLink=await mutate("save_public_link",{name:d.name,publication_id:d.publication_id,language:d.language,expires_at:d.expires_at});delete ui.drafts["public-link"];};
handlers.template=async(f,d)=>{await mutate("save_template",{...(ui.template?{id:ui.template.id,expected_version:ui.template.version}:{}),template:{name:d.name,kind:d.kind,language:d.language,subject:d.subject,body:d.body}});ui.template=null;delete ui.drafts.template;};
handlers["message-preview"]=async(f,d)=>{ui.messageParams={assignment_id:d.assignment_id,template_id:d.template_id,followup_key:d.followup_key||undefined,at:stamp()};ui.messagePreview=await call("preview_message",ui.messageParams);};
handlers["message-retain"]=async()=>{if(!ui.messagePreview)throw Error("Review the original complete message first.");const result=await mutate("retain_message",{...ui.messageParams,review_sha256:ui.messagePreview.review_sha256});ui.selectedMessage=result.message;ui.messagePreview=null;};
handlers["delivery-preview"]=async(f,d)=>{const source=await filePayload(f.elements.file.files[0]);ui.deliveryInput={...source,format:d.format,...(d.format==="JSON"?{mapping:json(d.mapping,{})}:{})};ui.delivery=await call("preview_delivery",ui.deliveryInput);};
handlers["delivery-retain"]=async()=>{await mutate("receive_delivery",{...ui.deliveryInput,review_sha256:ui.delivery.review_sha256});if(ui.selectedMessage)ui.selectedMessage=(await call("get_message",{id:ui.selectedMessage.id})).message;ui.delivery=null;};
handlers["followups-read"]=async(f,d)=>{ui.followups=await call("followups",{at:d.at});};
handlers["followup-log"]=async(f,d)=>{await mutate("log_followup",{assignment_id:d.assignment_id,channel:d.channel,outcome:d.outcome,at:d.at,note:d.note,original_source:{kind:"CONTACT_RECORD",reference:d.original_source},...(d.expected_response_at?{expected_response_at:d.expected_response_at}:{})});delete ui.drafts["followup-log"];};
handlers["history-read"]=async(f,d)=>{ui.historyFilter={kind:d.kind,id:d.id};const items=[];let offset=0,total=Infinity;while(offset<total){const page=await call("history",{...ui.historyFilter,offset,limit:500});items.push(...page.items);total=page.total;if(!page.items.length)break;offset+=page.items.length;}ui.history={items,total};};
const actions={
tab:async key=>{ui.tab=key;location.hash=key;ui.error=null;},
refresh:async()=>refresh(),
logout:async()=>{await request("/api/logout",{});ui.session={authenticated:false};ui.state=null;},
page:async key=>{const[k,p]=key.split("|");ui.pages[k]=Math.max(0,Number(p));},
recover:recoverPending,
retry:async()=>{if(!ui.pending)return;await recoverPending();if(ui.pending&&!ui.pending.bodyMissing)await executePending();},
"contact-bulk-create":async()=>{const linked=new Set((ui.contactSource?.contact_links||[]).map(x=>x.row_id));for(const r of ui.contactSource?.report.mapped.rows||[]){if(r.valid&&!linked.has(r.id)&&!r.warnings.some(w=>w.code==="DUPLICATE_CONTACT_CANDIDATE")&&!ui.contactChoices[r.id]?.action)ui.contactChoices[r.id]={...(ui.contactChoices[r.id]||{}),action:"CREATE",kind:"PERSON"};}ui.notice="Valid new rows without duplicate candidates are selected for creation. Review remaining rows and differing company names before receiving.";},
"edit-company":async key=>{ui.company=ui.state.companies.find(c=>c.id===key);delete ui.drafts.company;},
"edit-contact":async key=>{ui.contact=ui.state.contacts.find(c=>c.id===key);delete ui.drafts.contact;},
assignment:async key=>{ui.selectedAssignment=await call("get_assignment",{id:key});delete ui.drafts["assignment-edit"];},
"public-link":async key=>{ui.publicLink=await call("get_public_link",{id:key});},
template:async key=>{ui.template=ui.state.templates.find(t=>t.id===key);delete ui.drafts.template;},
"install-templates":async()=>mutate("install_templates",{}),
"sync-notifications":async()=>{const result=await mutate("sync_notifications",{at:stamp()});ui.notice="Prepared "+result.messages.length+" original response notices; "+result.skipped.length+" require contact or template review.";if(result.skipped.length)ui.error=j(result.skipped);},
message:async key=>{ui.selectedMessage=(await call("get_message",{id:key})).message;},
dispatch:async key=>{const result=await mutate("dispatch",{id:key});ui.selectedMessage=(await call("get_message",{id:key})).message;ui.notice="Original provider outcome: "+(result.delivery?.state||ui.selectedMessage.delivery.state)+".";},
"cancel-message":async key=>{const message=(await call("get_message",{id:key})).message;await mutate("cancel_message",{id:key,expected_version:message.version});ui.selectedMessage=(await call("get_message",{id:key})).message;},
"record-unknown":async key=>{await mutate("record_unknown",{id:key});ui.selectedMessage=(await call("get_message",{id:key})).message;},
"process-due":async key=>{const result=await mutate("process_due",{send:key==="send"});ui.notice="Configured follow-up job completed. "+j(result.job);ui.followups=await call("followups",{at:stamp()});},
"prepare-followup":async key=>{const item=ui.followups.items.find(x=>x.key===key);const a=ui.state.assignments.find(x=>x.id===item.assignment_id);ui.messageParams={assignment_id:a.id,template_id:"standard-reminder-"+a.language.toLowerCase(),followup_key:key,at:stamp()};ui.messagePreview=await call("preview_message",ui.messageParams);delete ui.drafts["message-preview"];ui.tab="messages";},
"open-public-response":async()=>{const result=ui.publicResult;await request("/api/session",{role:"respondent",respondent_id:result.respondent_id,access_code:result.access_code});location.assign(result.entry_path);}
};
function contactFields(c={},language="EN",company=true){const fr=language==="FR";return(company?field(fr?"Entreprise":"Company","company_name",c.company_name,"text","required"):"")+field(fr?"Nom de la personne-ressource":"Contact name","contact_name",c.contact_name,"text","required")+field(fr?"Courriel":"Email","email",c.email,"email")+field(fr?"Téléphone":"Phone","phone",c.phone)+area(fr?"Adresse postale":"Postal address","postal_address",c.postal_address)+field(fr?"Pays":"Country","country",c.country)+select(fr?"Langue":"Language","language",[{value:"EN",label:"English"},{value:"FR",label:"Français"}],c.language||language);}
function renderPublic(){const p=ui.publicInfo,fr=p.language==="FR";root.innerHTML='<main class="public-entry"><h1>'+h(p.questionnaire_title)+'</h1><p>'+h(p.organization_name)+' · '+h(p.case_reference)+'</p><p>'+h(p.case_title)+'</p><p>'+h(fr?"Date limite : ":"Response due: ")+h(p.due_at)+'</p>'+(ui.error?'<p class="notice" role="alert">'+h(ui.error)+'</p>':"")+(ui.publicResult?'<h2>'+h(fr?"Votre accès au questionnaire":"Your questionnaire access")+'</h2><p>'+h(ui.publicResult.company_name)+'</p><p>'+h(fr?"Code d’accès privé : ":"Private access code: ")+'<strong>'+h(ui.publicResult.access_code)+'</strong></p>'+button(fr?"Ouvrir votre questionnaire":"Open your questionnaire","open-public-response"):'<p>'+h(fr?"Saisissez les coordonnées de votre entreprise. Elles seront examinées par le personnel responsable du questionnaire.":"Enter your company’s contact information. Staff will review it with the original questionnaire assignment.")+'</p>'+form("public-entry",contactFields({},p.language)+submit(fr?"Créer mon accès":"Create my access"),false))+'<p>'+h(fr?"Assistance : ":"For assistance: ")+h(p.support_contact)+'</p></main>';}
async function renderRespondent(){if(!ui.respondentContact){try{ui.respondentContact=await call("respondent_contact",{respondent_id:ui.session.respondent_id});}catch(e){root.innerHTML='<main><h1>Contact information</h1><p>'+h(errorText(e))+'</p><a href="/respondent/'+h(ui.session.respondent_id)+'">Return to your questionnaire</a></main>';return;}}const value=ui.respondentContact,fr=value.contact.language==="FR";root.innerHTML='<main class="public-entry"><h1>'+h(fr?"Vos coordonnées":"Your contact information")+'</h1><p>'+h(value.contact.company_name)+'</p><a href="/respondent/'+h(ui.session.respondent_id)+'">'+h(fr?"Retourner au questionnaire":"Return to your questionnaire")+'</a>'+(ui.error?'<p role="alert" class="notice">'+h(ui.error)+'</p>':"")+(ui.notice?'<p role="status">'+h(ui.notice)+'</p>':"")+form("respondent-contact",contactFields(value.contact,value.contact.language,false)+submit(fr?"Enregistrer les coordonnées":"Save contact information"),false)+'</main>';}
handlers["public-entry"]=async(f,d)=>{if(!ui.publicRequest)ui.publicRequest={token:ui.publicToken,request_id:id(),contact:{...d,kind:"PUBLIC_ENTRY"}};const response=await request("/api/outreach/public-entry",ui.publicRequest);ui.publicResult=response.result;ui.error=null;renderPublic();};
handlers["respondent-contact"]=async(f,d)=>{const old=ui.respondentContact;if(!ui.respondentRequest)ui.respondentRequest={respondent_id:ui.session.respondent_id,expected_version:old.version,request_id:id(),contact:{contact_name:d.contact_name,email:d.email,phone:d.phone,postal_address:d.postal_address,country:d.country,language:d.language}};await call("update_respondent_contact",ui.respondentRequest);ui.respondentRequest=null;ui.respondentContact=await call("respondent_contact",{respondent_id:ui.session.respondent_id});ui.notice=ui.respondentContact.contact.language==="FR"?"Coordonnées enregistrées.":"Contact information saved.";};
root.addEventListener("input",event=>{const el=event.target;if(el.id==="reason")ui.reason=el.value;if(el.id==="actor")sessionStorage.setItem("atssc-operator",el.value);if(el.dataset.choice){const row=el.dataset.row;ui.contactChoices[row]={...(ui.contactChoices[row]||{}),[el.dataset.choice]:el.value};}captureDraft(el.closest("form"));});
root.addEventListener("change",event=>{const el=event.target;if(el.dataset.choice){const row=el.dataset.row;ui.contactChoices[row]={...(ui.contactChoices[row]||{}),[el.dataset.choice]:el.value};}captureDraft(el.closest("form"));});
root.addEventListener("submit",async event=>{const f=event.target.closest("form[data-form]");if(!f)return;event.preventDefault();const method=handlers[f.dataset.form];if(!method)return;captureDraft(f);ui.error=null;const data=Object.fromEntries(new FormData(f));try{await method(f,data);}catch(e){ui.error=errorText(e)+(e?.detail?" · "+j(e.detail):"");if(f.dataset.form==="public-entry"&&e.definitive)ui.publicRequest=null;if(f.dataset.form==="respondent-contact"&&e.definitive)ui.respondentRequest=null;}finally{if(ui.publicInfo)renderPublic();else render();}});
root.addEventListener("click",async event=>{const b=event.target.closest("[data-action]");if(!b||b.disabled)return;const run=actions[b.dataset.action];if(!run)return;try{ui.error=null;await run(b.dataset.id);}catch(e){showError(e);}finally{if(ui.publicInfo)renderPublic();else render();}});
window.addEventListener("hashchange",()=>{const tab=location.hash.slice(1);if(tabs.some(x=>x[0]===tab)){ui.tab=tab;render();}});
async function boot(){try{if(location.pathname.startsWith("/public/entry/")){ui.publicToken=decodeURIComponent(location.pathname.slice("/public/entry/".length));ui.publicInfo=await request("/api/outreach/public?token="+encodeURIComponent(ui.publicToken));renderPublic();return;}ui.tab=tabs.some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):"case";ui.session=await request("/api/session");if(ui.session.authenticated&&ui.session.role==="operator"){await refresh();try{ui.pending=JSON.parse(sessionStorage.getItem(pendingKey())||"null");}catch{}}render();}catch(e){root.innerHTML='<main><h1>Companies and communications</h1><p role="alert">'+h(errorText(e))+'</p>'+button("Reload","reload")+'</main>';}}
actions.reload=async()=>location.reload();
boot();
